Ext._define('rh.pvf.sendpointsheet.PointJustificationGrid', {
    extend: 'core.RestfulGrid',

    restWindow: 'rh.pvf.sendpointsheet.PointJustificationWindow',

    configOrderToolBar: ['add', 'edit', 'remove', '->', 'showCancelled'], 

    initComponent: function() {

        rh.pvf.sendpointsheet.PointJustificationGrid.superclass.initComponent.call(this);

        this.getStore().on('load', this.initialFilter, this);
    },
    
    initialFilter: function() {
        this.getStore().filter('cancelado', false);
    },

    getConfigActionsItems: function(cfg){
        if(!this._configActionsItems){
            this._configActionsItems = {
                add:{
                    text: 'Novo',
                    iconCls: 'icon-16px icon-core icon-core-add',
                    scope: this,
                    handler: this.createItem,
                },
                edit:{
                    text: 'Editar',
                    iconCls: 'icon-core icon-core-edit',
                    scope: this,
                    handler: this.updateItem,
                },
                remove:{
                    text: 'Cancelar',
                    iconCls: 'icon-core icon-core-delete',
                    scope: this,
                    handler: this.cancelaItem,
                },
                search:[
                    'Buscar por: ',
                    this.getKeywordField(cfg),
                    '-'
                ],
                download:[
                    '-',
                    {
                        text: 'Download',
                        iconCls: 'icon-core icon-core-csv',
                        scope: this,
                        handler: this.doDownload
                    }
                ],
                showCancelled: [
                    '-',
                    {
                        text: 'Mostrar justificativas canceladas',
                        iconCls: 'icon-core icon-core-run',
                        scope: this,
                        handler: this.MostrarJustificativasCanceladas
                    }
                ],
            };

        }
        return this._configActionsItems;
    },


    _realizarReq: function(params, nome_classe, nome_metodo){
        Ext.Ajax.request({
            url: toolkit.util.Normalize.controller_action(nome_classe,nome_metodo),
            params: params,
            success: function(request) {
                var obj = Ext.decode(request.responseText);
                var icon = obj.success == true ? Ext.Msg.INFO : Ext.Msg.ERROR;
                Ext.Msg.show({
                    // width:"200px",
                    title: 'Aviso',
                    icon: icon,
                    buttons: Ext.Msg.OK,
                    msg: obj.message
                });
                if(obj.success == true){ this.getStore().reload(); }
            },
            failure: function() {
                Ext.Msg.show({
                    title: this.title,
                    icon: Ext.Msg.ERROR,
                    buttons: Ext.Msg.OK,
                    msg: 'Recurso indisponivel no momento, tente novamente mais tarde.'
                });
            },
            scope: this
        });
    },



    cancelaItem: function(record) {

        if(!this.allowUpdate)
            return;

        if(record instanceof Ext.Button)
            record = undefined;

        var selecao = core.nullValue(record, this.getSelectionModel().getSelections());

        // if (!Ext.isArray(selecao)) selecao = [selecao];


        var selecionados = selecao.map(function(s){
            return [s.id]
        });
        
        var msg = 'Tem certeza que deseja calcular todos os registros do período selecionado? ';
        msg += 'Os registros Deferidos e Indeferidos serão ignorados.';
        
        var params = {
            'selecionados': selecionados,
            'modulo': this.params.modulo,
            'num_selecao': selecionados.length
        }

        Ext.Msg.show({
            msg: msg,
            icon: Ext.Msg.QUESTION,
            buttons: Ext.Msg.YESNO,
            scope: this,
            fn: function (b) {
                if (b == 'no') return;

                params = params;
                this._realizarReq(params, 'PVFPointJustification', 'cancelar_justificativa');
            }
        });

    },


    MostrarJustificativasCanceladas: function(btn) {
        var store = this.getStore();
    
        if (btn.text === 'Mostrar justificativas canceladas') {
            store.clearFilter();
            btn.setText('Esconder justificativas canceladas');
        } else {
            store.clearFilter();
            store.filter('cancelado', false); 
            btn.setText('Mostrar justificativas canceladas');
        }
    },

    getColumnModel: function() {
        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    Ext._create('Ext.grid.RowNumberer'),
                    {header: 'Cod', dataIndex: 'pk', width: 50, hidden: true},
                    {header: 'Descricao', dataIndex: 'unicode', id: 'autoExpandColumn',hidden: true},
                    {header: 'Motivo', dataIndex: 'reason_type_str', width: 120},
                    {header: 'Início', dataIndex: 'start_date', width: 90, renderer: Ext.util.Format.dateRenderer('d/m/Y')},
                    {header: 'Fim', dataIndex: 'end_date', width: 90, renderer: Ext.util.Format.dateRenderer('d/m/Y')},
                    {header: 'Observação', dataIndex: 'observation', width: 90,hidden: true},
                    {header: 'Cancelado', dataIndex: 'cancelado', width: 90, renderer: function(value) { return (value ? 'SIM' : 'NÃO'); }},
                    {header: 'Origem', dataIndex: 'origem_display', width: 90, hidden: true},
                    {header: 'Quantidade Horas', dataIndex: 'number_hours_str', width: 150},
                    {header: 'attachment', dataIndex: 'attachment_unicode', width: 120,hidden: true},
                ]
            );

        return this._columnModel;
    }
});

core.RestfulGrid.register(
    'rh.pvf.sendpointsheet.PointJustificationRestful',
    'rh.pvf.sendpointsheet.PointJustificationGrid'
);